import { compareTimestamps } from "./timestamps.js";

/**
 * Order contacts for the import: the most recently updated first, so the
 * contacts that changed since the last import are at the top of the review
 * queue.
 *
 * @param {import("./merge.js").Contact[]} contacts
 * @returns {import("./merge.js").Contact[]}
 */
export function sortContacts(contacts) {
  return contacts.sort((a, b) => (compareTimestamps(a.updatedAt, b.updatedAt) > 0 ? -1 : 1));
}

